CREATE TABLE orders(id BIGSERIAL PRIMARY KEY,customer_name VARCHAR(160) NOT NULL,status VARCHAR(40) NOT NULL DEFAULT 'PLACED',total NUMERIC(12,2) NOT NULL DEFAULT 0,created_at TIMESTAMPTZ DEFAULT now()); CREATE TABLE order_items(id BIGSERIAL PRIMARY KEY,order_id BIGINT REFERENCES orders(id) ON DELETE CASCADE,product_id BIGINT REFERENCES products(id),quantity NUMERIC(12,3) NOT NULL,unit_price NUMERIC(12,2) NOT NULL); CREATE TABLE order_status_history(id BIGSERIAL PRIMARY KEY,order_id BIGINT REFERENCES orders(id),status VARCHAR(40),created_at TIMESTAMPTZ DEFAULT now());